import React, { useState, createContext, useEffect } from 'react';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { View, Text, TextInput, TouchableOpacity, FlatList, Alert, StyleSheet, ScrollView } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { WebView } from 'react-native-webview';

const EscrowContext = createContext();
const Stack = createNativeStackNavigator();

// ===== CONFIG - PUT YOUR PAYSTACK KEY HERE =====
const PAYSTACK_PUBLIC_KEY = "pk_test_YOUR_KEY_HERE"; // replace with pk_live_...
const PLATFORM_FEE_PERCENT = 2;

// ===== AUTH + ESCROW STORAGE =====
function useEscrow() {
  const [user, setUser] = useState(null);
    const [escrows, setEscrows] = useState([]);
      const [balance, setBalance] = useState(0);

        useEffect(()=>{ load() }, []);
          const load = async ()=>{
              const u = await AsyncStorage.getItem('user');
                  const e = await AsyncStorage.getItem('escrows');
                      const b = await AsyncStorage.getItem('balance');
                          if(u) setUser(JSON.parse(u));
                              if(e) setEscrows(JSON.parse(e));
                                  if(b) setBalance(Number(b));
                                    };
                                      const saveEscrows = async (data)=>{ setEscrows(data); await AsyncStorage.setItem('escrows', JSON.stringify(data)); }
                                        const login = async (email)=>{ const u={email}; setUser(u); await AsyncStorage.setItem('user', JSON.stringify(u)); }
                                          const logout = async ()=>{ setUser(null); await AsyncStorage.removeItem('user'); }

                                            const createEscrow = async (buyerEmail, amount, description)=>{
                                                const fee = Math.round(amount * PLATFORM_FEE_PERCENT / 100);
                                                    const newEscrow = {
                                                          id: Date.now().toString(),
                                                                seller: user.email,
                                                                      buyerEmail, amount, description, fee,
                                                                            status: 'pending_payment', // pending_payment -> funded -> delivered -> released
                                                                                  createdAt: new Date().toISOString(),
                                                                                        escrowAccount: `ESC-${Date.now().toString().slice(-6)}` // where money is held
                                                                                            };
                                                                                                await saveEscrows([newEscrow, ...escrows]);
                                                                                                    return newEscrow;
                                                                                                      };

                                                                                                        const releaseFunds = async (id)=>{
                                                                                                            const updated = escrows.map(es=> es.id===id ? {...es, status:'released'} : es);
                                                                                                                await saveEscrows(updated);
                                                                                                                    const esc = escrows.find(e=>e.id===id);
                                                                                                                        const payout = esc.amount - esc.fee;
                                                                                                                            const newBal = balance + payout;
                                                                                                                                setBalance(newBal);
                                                                                                                                    await AsyncStorage.setItem('balance', String(newBal));
                                                                                                                                      };

                                                                                                                                        return { user, escrows, balance, login, logout, createEscrow, releaseFunds, saveEscrows };
                                                                                                                                        }

                                                                                                                                        // ===== SCREENS =====
                                                                                                                                        function LoginScreen({ navigation }){
                                                                                                                                          const { login } = React.useContext(EscrowContext);
                                                                                                                                            const [email, setEmail] = useState('');
                                                                                                                                              return (
                                                                                                                                                  <View style={s.container}>
                                                                                                                                                        <Text style={s.title}>🛡️ EscrowLock Gold V2</Text>
                                                                                                                                                              <Text style={s.sub}>Secure Paystack Escrow</Text>
                                                                                                                                                                    <TextInput style={s.input} placeholder="Your Email (Seller)" value={email} onChangeText={setEmail} autoCapitalize='none' />
                                                                                                                                                                          <TouchableOpacity style={s.btn} onPress={async()=>{
                                                                                                                                                                                  if(!email.includes('@')) return Alert.alert('Enter valid email');
                                                                                                                                                                                          await login(email); navigation.replace('Dashboard');
                                                                                                                                                                                                }}><Text style={s.btnT}>Login / Register</Text></TouchableOpacity>
                                                                                                                                                                                                      <Text style={s.small}>No password needed for MVP. Funds held in Paystack secure escrow account before withdrawal.</Text>
                                                                                                                                                                                                          </View>
                                                                                                                                                                                                            );
                                                                                                                                                                                                            }

                                                                                                                                                                                                            function DashboardScreen({ navigation }){
                                                                                                                                                                                                              const { user, escrows, balance, logout } = React.useContext(EscrowContext);
                                                                                                                                                                                                                const myEscrows = escrows.filter(e=> e.seller===user?.email);
                                                                                                                                                                                                                  const totalHeld = myEscrows.filter(e=> e.status==='funded').reduce((a,b)=>a+b.amount,0);
                                                                                                                                                                                                                    
                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                          <View style={s.container}>
                                                                                                                                                                                                                                <View style={s.header}>
                                                                                                                                                                                                                                        <Text style={s.title}>Hello, {user?.email.split('@')[0]}</Text>
                                                                                                                                                                                                                                                <TouchableOpacity onPress={async()=>{ await logout(); navigation.replace('Login'); }}><Text style={{color:'red'}}>Logout</Text></TouchableOpacity>
                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                  <View style={s.card}>
                                                                                                                                                                                                                                                                          <Text style={s.label}>Escrow Wallet Balance (Ready to withdraw)</Text>
                                                                                                                                                                                                                                                                                  <Text style={s.big}>₦{balance.toLocaleString()}</Text>
                                                                                                                                                                                                                                                                                          <TouchableOpacity style={[s.btn,{marginTop:10}]} onPress={()=>navigation.navigate('Withdraw')}><Text style={s.btnT}>Withdraw to Bank</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                </View>

                                                                                                                                                                                                                                                                                                      <View style={s.card}>
                                                                                                                                                                                                                                                                                                              <Text style={s.label}>Funds Held in Escrow Account</Text>
                                                                                                                                                                                                                                                                                                                      <Text style={s.big}>₦{totalHeld.toLocaleString()}</Text>
                                                                                                                                                                                                                                                                                                                              <Text style={s.small}>Money buyers paid is here. Released after buyer confirms delivery.</Text>
                                                                                                                                                                                                                                                                                                                                    </View>

                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity style={s.btn} onPress={()=>navigation.navigate('Create')}><Text style={s.btnT}>+ Create Secure Escrow</Text></TouchableOpacity>

                                                                                                                                                                                                                                                                                                                                                <Text style={[s.label,{marginTop:15}]}>My Escrows</Text>
                                                                                                                                                                                                                                                                                                                                                      <FlatList data={myEscrows} keyExtractor={i=>i.id} renderItem={({item})=>(
                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={s.card} onPress={()=>navigation.navigate('Detail',{id:item.id})}>
                                                                                                                                                                                                                                                                                                                                                                        <Text style={{fontWeight:'bold'}}>{item.buyerEmail} - ₦{item.amount}</Text>
                                                                                                                                                                                                                                                                                                                                                                                  <Text>{item.description}</Text>
                                                                                                                                                                                                                                                                                                                                                                                            <Text style={{color: item.status==='released'?'green': item.status==='funded'?'orange':'gray'}}>● {item.status.toUpperCase()} | {item.escrowAccount}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                          )} />
                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                function CreateScreen({ navigation }){
                                                                                                                                                                                                                                                                                                                                                                                                                  const { createEscrow } = React.useContext(EscrowContext);
                                                                                                                                                                                                                                                                                                                                                                                                                    const [buyer, setBuyer] = useState(''); const [amount, setAmount] = useState(''); const [desc, setDesc] = useState('');
                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                          <ScrollView style={s.container}>
                                                                                                                                                                                                                                                                                                                                                                                                                                <Text style={s.title}>Create Escrow</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={s.small}>Buyer pays, Paystack holds money in {`escrow account`}, you deliver, buyer confirms, you withdraw to any bank.</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                            <TextInput style={s.input} placeholder="Buyer Email" value={buyer} onChangeText={setBuyer} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TextInput style={s.input} placeholder="Amount (₦)" value={amount} onChangeText={setAmount} keyboardType='numeric' />
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TextInput style={[s.input,{height:80}]} placeholder="What is buyer paying for?" value={desc} onChangeText={setDesc} multiline />
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={s.btn} onPress={async()=>{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if(!buyer || !amount) return Alert.alert('Fill all');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const esc = await createEscrow(buyer, Number(amount), desc);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      navigation.replace('Pay', { escrow: esc });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }}><Text style={s.btnT}>Create Secure Escrow</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={{marginTop:10, backgroundColor:'#e8f5e9', padding:10, borderRadius:8}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Text>✅ Paystack holds money</Text><Text>✅ Buyer confirms delivery</Text><Text>✅ You get paid instantly to escrow wallet</Text><Text>✅ 2% platform fee</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </ScrollView>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function PayScreen({ route, navigation }){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { escrow } = route.params;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const { saveEscrows, escrows } = React.useContext(EscrowContext);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Paystack checkout URL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const paystackUrl = `https://paystack.com/pay/escrowlock-test`; // replace with your generated payment link logic

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // For MVP we simulate Paystack success - in production you use Paystack API to initialize transaction
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <View style={{flex:1}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={{padding:15, backgroundColor:'#fff'}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Text style={s.title}>Buyer Payment: ₦{escrow.amount}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text>Escrow ID: {escrow.escrowAccount}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Text style={s.small}>This is where buyer pays. Money goes to Paystack escrow holding account, not directly to you.</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity style={s.btn} onPress={async()=>{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Simulate successful funding
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const updated = escrows.map(e=> e.id===escrow.id ? {...e, status:'funded'}:e);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          await saveEscrows(updated);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Alert.alert('Payment Successful', '₦'+escrow.amount+' is now held in escrow account '+escrow.escrowAccount);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              navigation.replace('Dashboard');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }}><Text style={s.btnT}>Simulate Buyer Paid (Test Mode)</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={s.small}>Replace this with real Paystack WebView: use https://api.paystack.co/transaction/initialize on your backend</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {/* Uncomment for real Paystack */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {/* <WebView source={{uri: paystackUrl}} /> */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function DetailScreen({ route, navigation }){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { id } = route.params;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const { escrows, releaseFunds } = React.useContext(EscrowContext);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const esc = escrows.find(e=>e.id===id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if(!esc) return <Text>Not found</Text>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={s.container}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Text style={s.title}>Escrow {esc.escrowAccount}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <View style={s.card}><Text>Buyer: {esc.buyerEmail}</Text><Text>Amount: ₦{esc.amount}</Text><Text>Fee (2%): ₦{esc.fee}</Text><Text>You will receive: ₦{esc.amount-esc.fee}</Text><Text>Status: {esc.status}</Text><Text>Description: {esc.description}</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {esc.status==='funded' && <TouchableOpacity style={s.btn} onPress={async()=>{ await releaseFunds(id); Alert.alert('Released','Funds moved to your withdrawable balance'); navigation.goBack(); }}><Text style={s.btnT}>Buyer Confirmed Delivery - Release to Wallet</Text></TouchableOpacity>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {esc.status==='released' && <Text style={{color:'green', fontWeight:'bold', marginTop:20}}>✅ Funds released to your wallet. Go withdraw to bank.</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function WithdrawScreen(){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const { balance } = React.useContext(EscrowContext);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const [bank, setBank] = useState(''); const [acct, setAcct] = useState('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={s.container}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={s.title}>Withdraw to Bank</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={s.card}><Text style={s.big}>₦{balance.toLocaleString()} Available</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TextInput style={s.input} placeholder="Bank Name (e.g. GTB, Access)" value={bank} onChangeText={setBank} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TextInput style={s.input} placeholder="Account Number" value={acct} onChangeText={setAcct} keyboardType='numeric' />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity style={s.btn} onPress={()=>{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if(!bank || !acct) return Alert.alert('Enter bank details');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Alert.alert('Withdrawal Initiated', `₦${balance} will be sent to ${bank} - ${acct} via Paystack Transfer. (Integrate paystack transfer API in backend)`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }}><Text style={s.btnT}>Withdraw ₦{balance} Now</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={s.small}>In production: call Paystack Transfer API: POST https://api.paystack.co/transfer - money moves from your Paystack balance to customer's bank.</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            export default function App(){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const escrow = useEscrow();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <EscrowContext.Provider value={escrow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <NavigationContainer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Stack.Navigator>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Stack.Screen name="Login" component={LoginScreen} options={{headerShown:false}} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Stack.Screen name="Dashboard" component={DashboardScreen} options={{title:'EscrowLock Gold V2'}} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Stack.Screen name="Create" component={CreateScreen} options={{title:'New Escrow'}} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Stack.Screen name="Pay" component={PayScreen} options={{title:'Buyer Payment'}} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Stack.Screen name="Detail" component={DetailScreen} options={{title:'Escrow Details'}} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Stack.Screen name="Withdraw" component={WithdrawScreen} options={{title:'Withdraw'}} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </Stack.Navigator>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </NavigationContainer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </EscrowContext.Provider>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const s = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    container:{flex:1, padding:16, backgroundColor:'#f8fafc'},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      title:{fontSize:22, fontWeight:'bold', marginBottom:4},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sub:{color:'#666', marginBottom:15},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          input:{backgroundColor:'#fff', borderWidth:1, borderColor:'#ddd', borderRadius:10, padding:12, marginBottom:10},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            btn:{backgroundColor:'#0f5c2f', padding:14, borderRadius:10, alignItems:'center', marginTop:8},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              btnT:{color:'#fff', fontWeight:'bold'},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                card:{backgroundColor:'#fff', padding:12, borderRadius:10, marginBottom:10, elevation:2},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  label:{color:'#666', fontSize:12},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    big:{fontSize:26, fontWeight:'bold'},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      small:{fontSize:11, color:'#666', marginTop:5},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        header:{flexDirection:'row', justifyContent:'space-between', alignItems:'center', marginBottom:10}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });